/**
 * The shared EMISSION context every entity's `to-tf` module uses.
 * Entity-agnostic by definition — nothing in here may name a resource type.
 * (The extraction-side twin is src/engine/pull/context.ts.)
 */
/**
 * Key for the `workspaceAspects` map: an app and an element MAY share a
 * refName (the org catalog barrel disambiguates that case by renaming the
 * EXPORTED key, e.g. `catalog.tickets2` — see `src/catalog/org.ts`'s
 * `computeElementKeys` — but each token's own `refName` field is untouched,
 * so `refName` alone is not a unique map key). Keying by kind+refName keeps
 * an app "tickets" and an element "tickets" from colliding.
 */
export function workspaceAspectKey(kind, refName) {
    return `${kind}:${refName}`;
}
